window.kbPageData["views/entry/k-a6c4e4a315a36daa"] = {"key":"entry/k-a6c4e4a315a36daa","state":{"route":"entry/k-a6c4e4a315a36daa"},"node":{"id":"k-a6c4e4a315a36daa","mode":"k","title":"区域协调发展战略、区域重大战略、主体功能区战略和新型城镇化战略","type":"概念与词义","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["regional"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["经济"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"1.区域协调发展战略、区域重大战略、主体功能区战略和新型城镇化战略\n区域协调发展战略：党的十八大以来，党中央强化举措推进西部大开发、东北振兴、中\n部崛起和东部率先发展，推动实施区域协调发展战略成为我国空间治理的基础战略。\n——求是网\n区域重大战略：是指党的十八大以来实施的京津冀协同发展、长江经济带发…","sources":[{"id":"cc7e2aa6219f2cfa","label":"区域协调发展战略、区域重大战略、主体功能区战略和新型城镇化战略","topic":"发展与治理","category":"非时政","text":"1.区域协调发展战略、区域重大战略、主体功能区战略和新型城镇化战略\n区域协调发展战略：党的十八大以来，党中央强化举措推进西部大开发、东北振兴、中\n部崛起和东部率先发展，推动实施区域协调发展战略成为我国空间治理的基础战略。\n——求是网\n区域重大战略：是指党的十八大以来实施的京津冀协同发展、长江经济带发展、粤港澳\n大湾区建设、长三角一体化发展、黄河流域生态保护和高质量发展等若干区域发展战略。区\n域重大战略的实施充分考虑了我国国土空间类型多样、差别巨大的客观实际，旨在从不同空\n间尺度、区域类型和功能定位推动战略重点区域加快发展，发挥对区域经济发展布局的示范\n引领和辐射带动作用。\n——国家发改委\n主体功能区战略：主体功能区是基于不同区域的资源环境承载能力、现有开发密度和发\n展潜力等，将特定区域确定为特定主体功能定位类型的一种空间单元。按开发强度划分为优\n化开发、重点开发、限制开发和禁止开发四类地区，按主体功能划分为城市化地区、农产品\n主产区和重点生态功能区三类地区。2011 年，“十二五”规划纲要明确提出“实施主体功\n能区战略”，将其上升至国家战略层面，此后主体功能区战略一直是指导我国区域经济发展\n的重大战略。\n——国家治理网\n城镇化是现代化的必由之路，是解决农业、农村、农民问题的重要途径，是推动区域协\n调发展的有力支撑，是扩大内需和促进产业升级的重要抓手。深入实施以人为本的新型城镇\n化战略，要坚持以人民为中心的发展思想，坚持稳中求进工作总基调，完整准确全面贯彻\n新发展理念，加快构建新发展格局，着力推动高质量发展，以满足人民日益增长的美好生\n活需要为根本目的，以体制机制改革为动力，因势利导、顺势而为，因地制宜、分类施策，\n稳步提高城镇化质量和水平，充分释放新型城镇化蕴藏的巨大内需潜力，持续推动经济实现\n质的有效提升和量的合理增长，为中国式现代化提供强劲动力和坚实支撑。\n——坚持以人为本。把推进农业转移人口市民化作为新型城镇化首要任务，坚持人民城\n市人民建、人民城市为人民，充分尊重人的意愿，调动和发挥好人的积极性主动性创造性，\n促进人的全面发展和社会公平正义，使全体居民共享现代化发展成果。\n——坚持遵循规律。立足我国国情，遵循自然规律、经济规律特别是城市发展规律，统\n筹新型工业化、新型城镇化和乡村全面振兴，充分发挥市场在资源配置中的决定性作用，更\n好发挥政府作用，提高资源配置效率。\n——坚持分类施策。统筹各地区资源环境承载能力、功能定位、城镇化发展水平和人口\n规模，因地制宜确定城镇化建设重点方向，积极稳妥、扎实推进，不搞齐步走、“一刀切”，\n形成各具特色的发展路径。\n——坚持集约高效。在全国“三区三线”划定成果基础上，有效集聚各类要素，促进城\n镇发展与产业支撑、就业转移、人口集聚相统一，构建科学合理的城镇化格局，推动城乡融\n合、区域协调发展。\n——《深入实施以人为本的新型城镇化战略五年行动计划》","source":{"doc":"6cbfb01fe723bba64b75","first":37,"last":38,"page":37,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"regional","title":"区域协调与城乡融合"}],"units":{"k-a6c4e4a315a36daa":[]}};
